CREATE TABLE `cd_ai_chat` (
  `chat_id` bigint NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `user_id` bigint DEFAULT NULL COMMENT '发起人ID',
  `user_type` char(1) DEFAULT '1' COMMENT '用户类型：1系统用户(医生) 2小程序用户',
  `role` varchar(20) DEFAULT NULL COMMENT '角色：doctor/patient/family',
  `patient_id` bigint DEFAULT NULL COMMENT '关联患者ID',
  `patient_name` varchar(50) DEFAULT NULL COMMENT '关联患者姓名',
  `question` text COMMENT '用户提问',
  `answer` text COMMENT 'AI回答',
  `model` varchar(50) DEFAULT NULL COMMENT '模型名称',
  `prompt_tokens` int DEFAULT '0' COMMENT '输入tokens',
  `completion_tokens` int DEFAULT '0' COMMENT '输出tokens',
  `cost_time` bigint DEFAULT '0' COMMENT '耗时(毫秒)',
  `kb_refs` int DEFAULT '0' COMMENT '引用的知识库条目数',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`chat_id`),
  KEY `idx_user` (`user_id`,`user_type`),
  KEY `idx_patient` (`patient_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI健康助手会话记录';
