DROP TABLE IF EXISTS `cd_article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cd_article` (
  `article_id` bigint NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `category_name` varchar(50) DEFAULT '' COMMENT '分类名称',
  `disease_code` char(1) DEFAULT NULL COMMENT '关联病种',
  `summary` varchar(500) DEFAULT '' COMMENT '摘要',
  `content` longtext COMMENT '正文(HTML)',
  `cover_image` varchar(255) DEFAULT '' COMMENT '封面图',
  `publish_status` char(1) DEFAULT '0' COMMENT '发布状态(0草稿 1已发布)',
  `author` varchar(50) DEFAULT '' COMMENT '作者',
  `view_count` int DEFAULT '0' COMMENT '阅读量',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`article_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_status` (`publish_status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='科普文章表';
/*!40101 SET character_set_client = @saved_cs_client */;

