INSERT INTO `cd_article` VALUES (1,'高血压患者如何科学控盐',1,'高血压科普','1','每日食盐摄入应控制在5克以内，学会识别\"隐形盐\"，是控制血压最有效的生活方式干预之一。','<h3>为什么要控盐</h3><p>食盐的主要成分是氯化钠，摄入过多会导致体内水钠潴留、血容量增加，从而升高血压。研究显示，每日食盐摄入量每减少1克，收缩压平均可下降约1-2 mmHg。</p><h3>每日吃多少</h3><p>中国居民膳食指南建议，成人每日食盐摄入量不超过<strong>5克</strong>（约一啤酒瓶盖）。高血压患者应更严格，尽量控制在3-5克。</p><h3>如何识别隐形盐</h3><ul><li>酱油、蚝油、豆瓣酱等调味品含盐量很高；</li><li>腌制品、腊肉、咸菜、榨菜；</li><li>加工食品：火腿肠、方便面、薯片、话梅；</li><li>部分面包、挂面在制作时也加入了食盐。</li></ul><h3>实用小技巧</h3><ol><li>使用限盐勺，做菜出锅前再放盐；</li><li>用醋、柠檬、葱姜蒜、香辛料替代部分咸味；</li><li>购买包装食品时学会看营养成分表中的\"钠\"含量（1克钠≈2.5克盐）；</li><li>在外就餐主动要求少盐、少放酱油。</li></ol><p>配合规律监测血压、按时服药，控盐才能真正转化为血压的下降。</p>','','1','张医生',128,'2026-09-20 10:00:00','0','2026-10-07 20:04:25'),(2,'糖尿病饮食的黄金法则',2,'糖尿病科普','2','主食粗细搭配、控制升糖指数、定时定量，是糖尿病患者饮食管理的核心。','<h3>三大原则</h3><p>糖尿病饮食管理可概括为：<strong>总量控制、结构合理、定时定量</strong>。</p><h3>主食怎么吃</h3><ul><li>粗细搭配：白米面中掺入燕麦、糙米、荞麦、玉米等；</li><li>优选低升糖指数（GI）食物，如杂粮饭、全麦面包；</li><li>避免粥类煮得过烂，糊化程度越高升糖越快。</li></ul><h3>餐盘搭配法</h3><p>把餐盘分成四份：<br/>1/2 非淀粉类蔬菜，1/4 优质蛋白（鱼、蛋、瘦肉、豆制品），1/4 主食。</p><h3>进食顺序有讲究</h3><p>建议按\"先喝汤→再吃菜→再吃肉→最后吃主食\"的顺序，有助于减缓餐后血糖上升。</p><h3>需注意</h3><ul><li>水果选择低GI的（如苹果、柚子、草莓），且放在两餐之间、控制分量；</li><li>戒烟限酒，避免含糖饮料；</li><li>规律监测空腹和餐后血糖，及时与医生沟通调整方案。</li></ul>','','1','李医生',256,'2026-09-22 10:00:00','0','2026-10-07 20:04:25'),(3,'冠心病患者的运动处方',3,'冠心病科普','3','适度、规律的有氧运动有助于心脏康复，但需掌握强度、时间与禁忌。','<h3>运动的好处</h3><p>规律运动可改善心肌供血、降低血脂血压、增强心肺功能，是冠心病二级预防的重要组成部分。</p><h3>推荐方式</h3><ul><li>有氧运动为主：快走、慢跑、骑车、太极拳、游泳；</li><li>每周累计<strong>150分钟</strong>中等强度运动，可分散到每周5天、每次30分钟；</li><li>可配合轻度抗阻训练，但避免憋气用力。</li></ul><h3>强度怎么把握</h3><p>常用\"谈话测试\"：运动时能正常说话但不能唱歌，即为中等强度。也可用目标心率（约170-年龄）作为参考。</p><h3>注意事项</h3><ul><li>运动前热身5-10分钟，运动后缓慢放松；</li><li>避免清晨低温时段、饱餐后立即运动；</li><li>随身携带急救药物（如硝酸甘油）；</li><li>出现胸痛、胸闷、气促、头晕时应立即停止并就医。</li></ul>','','1','王医生',98,'2026-09-25 10:00:00','0','2026-10-07 20:04:25'),(4,'慢阻肺患者如何做呼吸训练',4,'慢阻肺科普','4','缩唇呼吸与腹式呼吸可改善通气效率、缓解气促，是慢阻肺肺康复的基础。','<h3>为什么练呼吸</h3><p>慢阻肺患者常因气道塌陷导致呼气困难、肺内残气增多。呼吸训练能改善通气效率、减轻呼吸困难。</p><h3>缩唇呼吸</h3><ol><li>用鼻子缓慢吸气（约2秒）；</li><li>嘴唇缩成\"吹口哨\"状，缓慢呼气（约4秒）；</li><li>呼气时间是吸气的2倍左右，每次练习5-10分钟，每日3-4次。</li></ol><h3>腹式呼吸</h3><ol><li>坐位或平卧，一手放胸口、一手放腹部；</li><li>用鼻吸气，让腹部隆起，胸部尽量不动；</li><li>缩唇缓慢呼气，腹部内收；</li><li>每次10-15分钟，每日2-3次。</li></ol><h3>其它建议</h3><ul><li>坚持戒烟，避免烟雾、粉尘、冷空气刺激；</li><li>在医生指导下规律使用吸入药物；</li><li>可结合步行、上肢锻炼等进行综合肺康复。</li></ul>','','1','赵医生',76,'2026-09-28 10:00:00','0','2026-10-07 20:04:25'),(5,'三高人群的日常监测指南',5,'健康生活方式','1','规律监测、认真记录、及时预警，是\"三高\"人群自我管理的关键环节。','<h3>为什么要监测</h3><p>高血压、高血糖、高血脂往往早期没有明显症状，规律监测才能及时发现异常、指导用药与生活方式调整。</p><h3>血压监测</h3><ul><li>建议每日早晚各测一次，测量前静坐5分钟；</li><li>保持固定时间、固定体位、固定手臂；</li><li>记录数值，关注波动趋势而非单次结果。</li></ul><h3>血糖监测</h3><ul><li>按医嘱监测空腹、餐后2小时血糖；</li><li>记录饮食、运动与血糖的对应关系；</li><li>出现心慌、出冷汗、手抖等低血糖症状及时处理。</li></ul><h3>血脂监测</h3><p>血脂一般每3-6个月复查一次，遵医嘱调整饮食与药物。</p><h3>建立健康档案</h3><p>把每次监测数据录入系统或健康档案，形成连续曲线，便于医生判断病情变化、及时预警和调整方案。同时保持低盐低脂饮食、规律作息、适度运动。</p>','','1','张医生',0,'2026-10-01 09:30:00','0','2026-10-07 20:04:25');
/*!40000 ALTER TABLE `cd_article` ENABLE KEYS */;
UNLOCK TABLES;

