  `guide_id` bigint NOT NULL AUTO_INCREMENT COMMENT '指导ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(50) DEFAULT '' COMMENT '患者姓名',
  `warning_id` bigint DEFAULT NULL COMMENT '关联预警ID',
  `guide_type` char(1) DEFAULT '1' COMMENT '指导类型(1调药 2用药提醒 3饮食推荐)',
  `content` varchar(1000) DEFAULT '' COMMENT '指导内容',
  `doctor_id` bigint DEFAULT NULL COMMENT '医生ID',
  `doctor_name` varchar(50) DEFAULT '' COMMENT '医生姓名',
  `guide_time` datetime DEFAULT NULL COMMENT '指导时间',
  `read_status` char(1) DEFAULT '0' COMMENT '已读状态(0未读 1已读)',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`guide_id`),
  KEY `idx_patient` (`patient_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='远程指导表';
