INSERT INTO `cd_guide` VALUES (1,1,'张建国',23,'1','低盐饮食，每日食盐摄入控制在5g以内；减少腌制食品，多食新鲜蔬果。',2,'李明医生','2026-10-06 22:30:00','0','0','2026-10-06 22:30:00'),(2,1,'张建国',15,'3','规范服用降压药，晨起后测量血压并记录，如连续3天≥180mmHg请及时就诊。',2,'李明医生','2026-10-07 00:30:00','0','0','2026-10-07 00:30:00'),(3,1,'张建国',3,'3','血糖偏高，建议严格控制主食量，三餐定时定量，避免精制糖。',2,'李明医生','2026-10-07 02:30:00','1','0','2026-10-07 02:30:00'),(4,2,'李秀兰',17,'3','按医嘱服用抗血小板药物，注意观察有无牙龈出血、皮下瘀斑。',2,'李明医生','2026-10-06 18:30:00','0','0','2026-10-06 18:30:00'),(5,2,'李秀兰',22,'2','以散步、太极等中低强度有氧运动为主，每次20-30分钟，避免剧烈运动。',2,'李明医生','2026-10-06 20:30:00','0','0','2026-10-06 20:30:00'),(6,3,'王卫东',26,'1','继续低盐低脂饮食，控制体重，戒烟限酒。',2,'李明医生','2026-10-05 20:30:00','1','0','2026-10-05 20:30:00'),(7,3,'王卫东',21,'3','缬沙坦每日一次，晨起服用；血压稳定后可遵医嘱调整用量。',2,'李明医生','2026-10-05 22:30:00','0','0','2026-10-05 22:30:00'),(8,4,'陈美玲',23,'1','糖尿病饮食：定时定量，主食粗细搭配，控制碳水总量。',2,'李明医生','2026-10-05 18:30:00','0','0','2026-10-05 18:30:00'),(9,4,'陈美玲',17,'2','餐后30分钟散步20分钟，有助于控制餐后血糖。',2,'李明医生','2026-10-05 19:30:00','1','0','2026-10-05 19:30:00'),(10,4,'陈美玲',12,'4','建议3个月后复查糖化血红蛋白及肺功能。',2,'李明医生','2026-10-05 21:30:00','0','0','2026-10-05 21:30:00'),(11,5,'刘志强',11,'1','保持清淡饮食，每日食盐<5g，多吃含钾食物如香蕉、菠菜。',4,'李医生','2026-10-05 16:30:00','0','0','2026-10-05 16:30:00'),(12,6,'赵淑芬',26,'3','噻托溴铵吸入剂每日一次，吸入后漱口；家庭氧疗每日≥15小时。',2,'李明医生','2026-10-05 10:30:00','1','0','2026-10-05 10:30:00'),(13,6,'赵淑芬',30,'2','坚持缩唇呼吸与腹式呼吸训练，每日2次，每次15分钟。',2,'李明医生','2026-10-05 12:30:00','0','0','2026-10-05 12:30:00'),(14,6,'赵淑芬',1,'1','高蛋白、高热量、易消化饮食，少量多餐。',2,'李明医生','2026-10-05 11:30:00','0','0','2026-10-05 11:30:00'),(15,7,'孙明辉',33,'1','定时定量进餐，避免高糖水果，主食替换为杂粮饭。',4,'李医生','2026-10-05 14:30:00','1','0','2026-10-05 14:30:00'),(16,7,'孙明辉',19,'4','建议1个月后复查空腹血糖与餐后2小时血糖。',4,'李医生','2026-10-05 15:30:00','0','0','2026-10-05 15:30:00'),(17,7,'孙明辉',21,'3','格列美脲每日晨起服用，用药后务必进餐，警惕低血糖。',4,'李医生','2026-10-05 17:30:00','0','0','2026-10-05 17:30:00'),(18,8,'周文彬',29,'2','适度有氧运动，每周3次，每次30分钟，心率控制在(170-年龄)以内。',4,'李医生','2026-10-05 17:30:00','1','0','2026-10-05 17:30:00'),(19,1,'张建国',NULL,'2','接口验证：请按时服药并每日测血压',2,'李明医生','2026-10-07 22:40:54','0','2','2026-10-07 22:40:54');
