--
-- Table structure for table `cd_measure`
--

DROP TABLE IF EXISTS `cd_measure`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cd_measure` (
  `measure_id` bigint NOT NULL AUTO_INCREMENT COMMENT '监测记录ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(50) DEFAULT '' COMMENT '患者姓名',
  `device_id` bigint DEFAULT NULL COMMENT '设备ID',
  `disease_code` char(1) DEFAULT NULL COMMENT '病种编码',
  `indicator_code` varchar(32) NOT NULL COMMENT '指标编码',
  `indicator_name` varchar(50) DEFAULT '' COMMENT '指标名称',
  `value` decimal(10,2) NOT NULL COMMENT '指标数值',
  `unit` varchar(16) DEFAULT '' COMMENT '单位',
  `measure_time` datetime NOT NULL COMMENT '监测时间',
  `data_source` char(1) DEFAULT '1' COMMENT '数据来源(1设备 2手动)',
  `abnormal_flag` char(1) DEFAULT '0' COMMENT '异常标记(0正常 1异常)',
  `warning_id` bigint DEFAULT NULL COMMENT '关联预警ID',
  `create_time` datetime DEFAULT NULL COMMENT '入库时间',
  PRIMARY KEY (`measure_id`),
  KEY `idx_patient_time` (`patient_id`,`measure_time`),
  KEY `idx_indicator` (`indicator_code`)
) ENGINE=InnoDB AUTO_INCREMENT=197 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='监测数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

