--
-- Table structure for table `cd_message`
--

DROP TABLE IF EXISTS `cd_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cd_message` (
  `message_id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `receiver_id` bigint NOT NULL COMMENT '接收人ID',
  `receiver_type` char(1) DEFAULT '1' COMMENT '接收人类型(1系统用户 2小程序用户)',
  `msg_type` char(1) DEFAULT '1' COMMENT '消息类型(1系统 2预警 3用药 4复诊)',
  `title` varchar(200) DEFAULT '' COMMENT '标题',
  `content` varchar(1000) DEFAULT '' COMMENT '内容',
  `biz_type` varchar(20) DEFAULT '' COMMENT '业务类型',
  `biz_id` bigint DEFAULT NULL COMMENT '业务单据ID',
  `read_flag` char(1) DEFAULT '0' COMMENT '阅读状态(0未读 1已读)',
  `send_time` datetime DEFAULT NULL COMMENT '发送时间',
  PRIMARY KEY (`message_id`),
  KEY `idx_receiver` (`receiver_id`,`receiver_type`,`read_flag`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息通知表';
/*!40101 SET character_set_client = @saved_cs_client */;

