--

LOCK TABLES `cd_message` WRITE;
/*!40000 ALTER TABLE `cd_message` DISABLE KEYS */;
INSERT INTO `cd_message` VALUES (1,1,'3','1','高危预警提醒','患者张建国的收缩压达到196.00mmHg，已触发高危预警并自动联动急救。','warning',1,'0','2026-10-06 22:30:00'),(2,6,'3','1','高危预警提醒','患者赵淑芬的血氧SpO2降至85.50%，已触发高危预警并自动联动急救。','warning',7,'0','2026-10-07 00:30:00'),(3,2,'3','1','高危预警提醒','患者李秀兰的心率达到118.00次/分，已触发高危预警。','warning',4,'0','2026-10-07 02:30:00'),(4,1,'1','2','转诊审核通过','患者张建国的转诊申请已通过审核，接收医院：北京市第一人民医院。','referral',1,'1','2026-10-06 14:30:00'),(5,6,'1','2','待审核转诊','患者赵淑芬的转诊申请待您审核。','referral',2,'0','2026-10-07 14:30:00'),(6,1,'2','3','新绑定申请','家属张小明申请绑定患者赵淑芬，等待患者与医生确认。','bind',4,'0','2026-10-07 16:30:00');
