INSERT INTO `cd_patient_profile` VALUES (1,1,'张建国','A型RH阳性','青霉素过敏（2016年皮试阳性，用药后出现皮疹）；磺胺类药物过敏','父亲患高血压、脑卒中，60岁病故；母亲患2型糖尿病；兄长有冠心病史','高血压3级（2018-05确诊，现口服氨氯地平控制）；2型糖尿病（2020-05确诊）；脂肪肝（2023年体检发现）；2024年曾有短暂头晕发作，未遗留后遗症','2015年阑尾切除术；2021年白内障超声乳化手术（右眼）','苯磺酸氨氯地平片 5mg 每日2次口服；二甲双胍缓释片 0.5g 每日2次随餐口服','无明显残疾；膝关节退行性变，长距离行走及上下楼梯稍感吃力，雨天加重','口味偏咸，喜食腌菜、酱制品，每日食盐估计10~12g；主食以精米白面为主，蔬菜摄入偏少；偶有饮酒，每周2~3次，每次白酒约1两；早餐常在外买油条豆浆','晚间入睡偏晚，多在23:30以后；夜间起夜2次，睡眠易中断，实际睡眠约6小时；白天常说困倦，有午睡习惯约30分钟','整体情绪平稳，性格偏内向不爱表达；对长期服药略有抵触，觉得自己\"没感觉就不想吃药\"；近期因血压波动反复，出现过焦虑、担心拖累子女的情绪','以散步为主，每日早晚饭后各一次，每次约20分钟；近1个月因膝关节不适，运动量明显减少；无规律抗阻训练','家属在家观察：近一周清晨起床后自述头晕、后颈部发紧，多在服药前出现；10月7日晚间测血压偏高（约165/95mmHg）后自行加服了一次氨氯地平；近半月自觉口干、饮水增多，夜尿次数由1次增加到2次；家属发现其做菜口味仍偏咸，多次劝说不易见效','既往用药依从性不佳，需家属协助提醒服药；建议重点关注清晨血压升高与夜间起夜增多的情况；家属已同意配合记录每日早晚血压。','王医生','1','2026-10-08 15:20:00','0','王医生','2026-10-08 15:20:00','张小明','2026-10-08 15:20:00');
/*!40000 ALTER TABLE `cd_patient_profile` ENABLE KEYS */;
UNLOCK TABLES;

