DROP TABLE IF EXISTS `cd_warning`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cd_warning` (
  `warning_id` bigint NOT NULL AUTO_INCREMENT COMMENT '预警ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(50) DEFAULT '' COMMENT '患者姓名',
  `disease_code` char(1) DEFAULT NULL COMMENT '病种编码',
  `indicator_code` varchar(32) DEFAULT '' COMMENT '触发指标编码',
  `indicator_name` varchar(50) DEFAULT '' COMMENT '触发指标名称',
  `indicator_value` decimal(10,2) DEFAULT NULL COMMENT '触发时指标值',
  `unit` varchar(16) DEFAULT '' COMMENT '单位',
  `threshold_desc` varchar(200) DEFAULT '' COMMENT '触发的阈值描述',
  `rule_id` bigint DEFAULT NULL COMMENT '触发规则ID',
  `warning_level` char(1) DEFAULT '1' COMMENT '预警级别(1低危 2中危 3高危)',
  `handle_status` char(1) DEFAULT '0' COMMENT '处置状态(0待处理 1处理中 2已处理)',
  `handle_type` char(1) DEFAULT NULL COMMENT '处置方式(1电话 2问诊 3调药 4转诊)',
  `handle_content` varchar(500) DEFAULT NULL COMMENT '处置意见',
  `handle_by` varchar(50) DEFAULT '' COMMENT '处置人',
  `handle_time` datetime DEFAULT NULL COMMENT '处置时间',
  `emergency_linked` char(1) DEFAULT '0' COMMENT '是否联动急救(0否 1是)',
  `trigger_time` datetime DEFAULT NULL COMMENT '触发时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`warning_id`),
  KEY `idx_patient` (`patient_id`),
  KEY `idx_level_status` (`warning_level`,`handle_status`),
  KEY `idx_trigger_time` (`trigger_time`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='预警记录表';
