DROP TABLE IF EXISTS `cd_warning_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cd_warning_rule` (
  `rule_id` bigint NOT NULL AUTO_INCREMENT COMMENT '规则ID',
  `rule_name` varchar(100) NOT NULL COMMENT '规则名称',
  `disease_code` char(1) NOT NULL COMMENT '病种编码',
  `indicator_code` varchar(32) NOT NULL COMMENT '指标编码',
  `indicator_name` varchar(50) DEFAULT '' COMMENT '指标名称',
  `operator` varchar(8) DEFAULT '>=' COMMENT '比较符(>= <= > < =)',
  `threshold_value` decimal(10,2) NOT NULL COMMENT '阈值',
  `threshold_desc` varchar(200) DEFAULT '' COMMENT '阈值描述',
  `warning_level` char(1) DEFAULT '1' COMMENT '预警级别(1低危 2中危 3高危)',
  `duration_minutes` int DEFAULT '0' COMMENT '持续时长(分钟)',
  `action_desc` varchar(500) DEFAULT '' COMMENT '处置建议',
  `status` char(1) DEFAULT '0' COMMENT '状态(0正常 1停用)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`rule_id`),
  KEY `idx_disease_indicator` (`disease_code`,`indicator_code`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='预警规则表';
/*!40101 SET character_set_client = @saved_cs_client */;

