--
-- Table structure for table `kb_document`
--

DROP TABLE IF EXISTS `kb_document`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kb_document` (
  `doc_id` bigint NOT NULL AUTO_INCREMENT COMMENT '文档ID',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `kb_type` char(1) DEFAULT '1' COMMENT '知识类型：1标准来源库 2辅助解释库',
  `disease_code` char(1) DEFAULT NULL COMMENT '病种：1高血压 2糖尿病 3冠心病 4慢阻肺',
  `category` varchar(50) DEFAULT NULL COMMENT '文档分类：指南/规范/科普/FAQ/专家说明',
  `summary` varchar(500) DEFAULT NULL COMMENT '摘要',
  `content` longtext COMMENT '正文内容',
  `publisher` varchar(100) DEFAULT NULL COMMENT '发布单位/来源机构',
  `publish_date` varchar(20) DEFAULT NULL COMMENT '发布日期',
  `effective_date` varchar(20) DEFAULT NULL COMMENT '生效日期',
  `applicable_scope` varchar(200) DEFAULT NULL COMMENT '适用人群',
  `version` varchar(50) DEFAULT NULL COMMENT '文件版本',
  `file_name` varchar(255) DEFAULT NULL COMMENT '原始文件名',
  `file_url` varchar(255) DEFAULT NULL COMMENT '原始文件地址',
  `file_hash` varchar(128) DEFAULT NULL COMMENT '文件哈希 SHA-256',
  `source_location` varchar(200) DEFAULT NULL COMMENT '原文位置',
  `tags` varchar(255) DEFAULT NULL COMMENT '标签，逗号分隔',
  `keywords` varchar(255) DEFAULT '' COMMENT '检索关键词(逗号分隔，供AI召回)',
  `status` char(1) DEFAULT '1' COMMENT '状态：0草稿 1已发布',
  `view_count` int DEFAULT '0' COMMENT '浏览次数',
  `create_by` varchar(64) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标记：0存在 2删除',
  PRIMARY KEY (`doc_id`),
  KEY `idx_kb_type` (`kb_type`),
  KEY `idx_kb_disease` (`disease_code`),
  KEY `idx_kb_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=200 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库文档';
/*!40101 SET character_set_client = @saved_cs_client */;

