INSERT INTO `kb_document` VALUES (1,'国家基层高血压防治管理指南（2024版）','1','1','指南','基层医疗机构高血压筛查、诊断、治疗与随访的规范依据，含血压测量方法、诊断标准、分级分层与用药原则。','第一章 血压测量与诊断标准\n\n1.1 诊室血压测量\n测量前受试者应安静休息至少5分钟，取坐位，裸露上臂，上臂与心脏处于同一水平。使用经校验的电子血压计或水银柱血压计，间隔1~2分钟重复测量，取2次读数的平均值记录。\n\n1.2 高血压诊断标准\n在未使用降压药物的情况下，非同日3次测量诊室血压，收缩压≥140 mmHg 和(或)舒张压≥90 mmHg，可诊断为高血压。\n\n1.3 家庭自测血压标准\n家庭自测血压的高血压诊断标准为≥135/85 mmHg，对应诊室血压的140/90 mmHg。\n\n第二章 心血管风险分层\n\n2.1 危险因素\n- 年龄：男性≥55岁，女性≥65岁\n- 吸烟或被动吸烟\n- 血脂异常\n- 糖耐量异常或空腹血糖受损\n- 腹型肥胖：男性腰围≥90cm，女性≥85cm\n- 早发心血管病家族史\n\n2.2 靶器官损害\n左心室肥厚、颈动脉内膜中层增厚或斑块、肾功能受损（eGFR下降、微量白蛋白尿）。\n\n2.3 分层规则\n低危：1级高血压且无危险因素；\n中危：1级高血压伴1~2个危险因素，或2级高血压无危险因素；\n高危：3级高血压，或合并靶器官损害、糖尿病、临床合并症。\n\n第三章 治疗原则\n\n3.1 降压目标\n一般高血压患者降至140/90 mmHg以下；能耐受者及合并糖尿病、冠心病、慢性肾病者进一步降至130/80 mmHg以下。65~79岁老年人首先降至150/90 mmHg以下，如能耐受可降至140/90 mmHg以下。\n\n3.2 生活方式干预\n- 限盐：每人每日食盐摄入量不超过5克\n- 合理膳食：增加新鲜蔬菜、水果、低脂乳制品\n- 控制体重：BMI保持在18.5~23.9 kg/m²\n- 戒烟限酒\n- 规律运动：每周5~7次中等强度有氧运动，每次30分钟\n- 心理平衡，保证充足睡眠\n\n3.3 药物治疗\n常用五大类降压药：钙通道阻滞剂(CCB)、血管紧张素转换酶抑制剂(ACEI)、血管紧张素受体拮抗剂(ARB)、噻嗪类利尿剂、β受体阻滞剂。\n起始治疗可采用单药小剂量或联合治疗，优先推荐单片复方制剂以提高依从性。\n','国家卫生健康委员会','2024-03-01','2024-04-01','基层医疗机构医务人员','2024版','基层高血压防治管理指南2024.pdf',NULL,'a3f5c9d21b8e47f6a0c3d5e8f1b2a4c6d8e0f2a4b6c8d0e2f4a6b8c0d2e4f6a8','第三章 3.2 节','血压,阈值,分级,用药,生活方式','','1',11,'admin','2026-10-08 11:37:33','admin','2026-11-16 20:34:07','0'),(2,'中国2型糖尿病防治指南（2023版）','1','2','指南','2型糖尿病的诊断标准、血糖控制目标、并发症筛查与降糖药物选择。','第一章 诊断标准\n\n1.1 糖尿病诊断\n具有典型糖尿病症状（多饮、多尿、多食、不明原因体重下降）加上以下任一条件：\n- 随机血糖 ≥ 11.1 mmol/L\n- 空腹血糖 ≥ 7.0 mmol/L\n- OGTT 2小时血糖 ≥ 11.1 mmol/L\n- 糖化血红蛋白 HbA1c ≥ 6.5%\n\n无典型症状者需改日复查确认。\n\n1.2 糖尿病前期\n空腹血糖受损(IFG)：空腹血糖 6.1~6.9 mmol/L；\n糖耐量减低(IGT)：OGTT 2小时血糖 7.8~11.0 mmol/L。\n\n第二章 血糖控制目标\n\n2.1 一般成人目标\n- 空腹血糖：4.4~7.0 mmol/L\n- 非空腹血糖：<10.0 mmol/L\n- HbA1c：<7.0%\n\n2.2 个体化调整\n病程短、预期寿命长、无并发症者 HbA1c 可更严格（<6.5%）；\n老年、有严重低血糖史、合并严重并发症者 HbA1c 可放宽至 <8.0%。\n\n2.3 低血糖\n血糖 ≤ 3.9 mmol/L 即定义为低血糖。轻度表现为出汗、心悸、手抖、饥饿感；严重者可致意识障碍。发生低血糖应立即口服15g葡萄糖，15分钟后复测。\n\n第三章 并发症筛查\n\n3.1 糖尿病肾病\n确诊时即应筛查尿白蛋白/肌酐比值(UACR)与eGFR，之后每年至少1次。\n\n3.2 糖尿病视网膜病变\n确诊时进行眼底检查，无病变者每1~2年复查1次。\n\n3.3 糖尿病足\n每年检查足部皮肤、足背动脉搏动、10g尼龙丝触觉。\n\n第四章 生活方式与药物治疗\n\n4.1 医学营养治疗\n碳水化合物占总能量50%~60%，优先选择低升糖指数食物；蛋白质15%~20%；脂肪<30%。\n\n4.2 运动\n每周至少150分钟中等强度有氧运动，如快走、骑车、游泳，餐后1小时运动有助于降低餐后血糖。\n\n4.3 降糖药物\n二甲双胍为一线首选并贯穿治疗全程。合并动脉粥样硬化性心血管疾病优先选用GLP-1受体激动剂或SGLT2抑制剂；合并心衰优先SGLT2抑制剂。','中华医学会糖尿病学分会','2023-11-20','2024-01-01','2型糖尿病患者及基层医务人员','2023版','中国2型糖尿病防治指南2023.pdf',NULL,'b7d1e3f5a9c2b4d6e8f0a2c4b6d8e0f2a4c6b8d0e2f4a6c8b0d2e4f6a8c0b2d4','第二章 2.1 节','血糖,糖化血红蛋白,低血糖,饮食,运动','','1',3,'admin','2026-10-08 11:37:33','admin','2026-11-16 20:34:08','0'),(3,'慢性阻塞性肺疾病诊治指南（2021年修订版）','1','4','指南','慢阻肺的诊断、肺功能分级、稳定期与急性加重期处理原则。','第一章 定义与诊断\n\n慢阻肺是一种以持续气流受限为特征的常见、可预防、可治疗的慢性气道疾病。\n\n1.1 肺功能诊断标准\n吸入支气管舒张剂后，第一秒用力呼气容积与用力肺活量比值(FEV1/FVC) < 0.70，即确定存在持续气流受限。\n\n1.2 严重程度分级（按FEV1占预计值百分比）\n- GOLD 1 轻度：FEV1 ≥ 80%\n- GOLD 2 中度：50% ≤ FEV1 < 80%\n- GOLD 3 重度：30% ≤ FEV1 < 50%\n- GOLD 4 极重度：FEV1 < 30%\n\n第二章 症状评估\n\n2.1 mMRC呼吸困难量表\n0级：仅在剧烈活动时感到呼吸困难；\n1级：快走或上缓坡时气短；\n2级：由于呼吸困难比同龄人步行慢，或需停下休息；\n3级：平地步行约100米或数分钟后需停下喘气；\n4级：因明显呼吸困难不能离家，或穿衣脱衣时即气短。\n\n2.2 CAT评分\n共8个条目，总分0~40分。≥10分提示症状显著影响健康状态。\n\n第三章 血氧与氧疗\n\n3.1 血氧饱和度监测\n静息状态下 SpO2 ≤ 88% 提示存在慢性呼吸衰竭风险，应评估长期家庭氧疗指征。\n\n3.2 长期家庭氧疗指征\n- PaO2 ≤ 55 mmHg 或 SpO2 ≤ 88%\n- PaO2 55~60 mmHg 或 SpO2 = 89%，合并肺动脉高压、心力衰竭或红细胞增多症\n每日吸氧时间不少于15小时，目标 SpO2 达到 90% 以上。\n\n第四章 稳定期治疗\n\n4.1 戒烟\n戒烟是延缓肺功能下降最重要的干预措施。\n\n4.2 支气管舒张剂\n长效β2受体激动剂(LABA)与长效抗胆碱能药物(LAMA)是稳定期核心用药，优先推荐联合治疗。\n\n4.3 吸入装置\n应定期评估患者吸入技术，错误使用是治疗失败的重要原因。\n\n4.4 呼吸康复\n包括缩唇呼吸、腹式呼吸训练、运动训练与营养支持。缩唇呼吸可减少呼吸频率、改善通气。\n\n第五章 急性加重期\n\n5.1 识别\n呼吸困难加重、痰量增多、痰液变脓是急性加重三大表现。呼吸频率 ≥ 25 次/分、SpO2 明显下降提示重度加重，需立即就医。\n\n5.2 处理\n支气管舒张剂雾化、全身糖皮质激素短程使用、抗感染治疗、控制性氧疗（目标 SpO2 88%~92%）。','中华医学会呼吸病学分会','2021-04-01','2021-05-01','慢阻肺患者及呼吸科医务人员','2021修订版','慢阻肺诊治指南2021.pdf',NULL,'c9e1b3d5f7a2c4e6b8d0f2a4c6e8b0d2f4a6c8e0b2d4f6a8c0e2b4d6f8a0c2e4','第三章 3.1 节','血氧,肺功能,氧疗,呼吸康复','','1',1,'admin','2026-10-08 11:37:33','admin','2026-10-08 11:38:47','0'),(4,'高血压患者日常饮食与监测注意事项（科普）','2','1','科普','面向患者的通俗解读：在家怎么量血压、吃什么、注意哪些信号。','一、在家怎么正确量血压\n\n1. 测量前30分钟内不要吸烟、喝咖啡、剧烈运动，先去洗手间排空膀胱。\n2. 安静坐5分钟再开始测量，背靠椅背，双脚平放不要跷腿。\n3. 手臂裸露，放在桌面上与心脏同高。\n4. 每次测2~3遍，每遍间隔1~2分钟，取平均值。\n5. 建议固定在早晨起床后1小时内（服药前）和晚上睡前各测一次。\n\n二、血压到什么程度该警惕\n\n- 收缩压 140~159 或舒张压 90~99：属于1级高血压，需规律服药并复查。\n- 收缩压 160~179 或舒张压 100~109：属于2级高血压，应尽快联系医生调整用药。\n- 收缩压 ≥ 180 或舒张压 ≥ 110：属于3级高血压，若同时有剧烈头痛、视物模糊、胸痛、呼吸困难，请立即就医或拨打120。\n\n三、饮食上要做什么\n\n要少吃：\n- 咸菜、腊肉、香肠、酱料、方便面等高盐食品\n- 动物内脏、肥肉、油炸食品\n- 含糖饮料、甜点\n\n推荐多吃：\n- 新鲜蔬菜每天300~500克，深色蔬菜占一半\n- 新鲜水果每天200~350克\n- 全谷物、杂豆、薯类替代部分精米白面\n- 低脂或脱脂奶制品\n- 深海鱼、去皮禽肉、豆制品\n\n限盐小技巧：用限盐勺，出锅前再放盐，用醋、柠檬、葱姜蒜提味代替部分食盐。\n\n四、日常生活建议\n\n- 戒烟，尽量避免二手烟。\n- 限制饮酒，最好不饮酒。\n- 每周至少5天、每天30分钟中等强度运动，如快走、太极拳。\n- 保持规律作息，保证每天7~8小时睡眠，睡眠不足会引起血压波动。\n- 保持情绪平稳，长期紧张焦虑会升高血压。\n\n五、什么时候必须联系医生\n\n- 连续3天家庭血压 ≥ 140/90 mmHg\n- 服药后出现头晕、乏力、干咳、下肢水肿\n- 血压忽高忽低、波动明显\n- 出现胸闷、胸痛、心悸、夜间不能平卧','慢病管理系统知识库','2024-06-01','2024-06-01','高血压患者及家属','1.0','高血压患者科普手册.pdf',NULL,'d1f3a5c7e9b2d4f6a8c0e2b4d6f8a0c2e4b6d8f0a2c4e6b8d0f2a4c6e8b0d2','常见问题 第2节','血压,科普,饮食,限盐,家庭监测','','1',1,'admin','2026-10-08 11:37:33','admin','2026-10-08 11:38:48','0'),(5,'血糖监测常见问题解答（FAQ）','2','2','FAQ','患者最常问的血糖监测问题：什么时候测、测出来多少算高、饮食怎么配合。','Q1：一天当中什么时候测血糖最有意义？\n\nA：取决于治疗方式。\n- 仅生活方式干预者：每周测2~4次，可选空腹和餐后2小时。\n- 口服降糖药者：每周2~4次，重点关注空腹和餐后2小时。\n- 使用胰岛素者：根据方案增加频次，通常需测空腹、三餐后2小时及睡前。\n- 出现低血糖症状时应随时加测。\n\n餐后2小时血糖应从吃第一口饭开始计时，而不是吃完饭才开始计时，这是最常见的误区。\n\nQ2：血糖多少算控制得好？\n\nA：一般成人参考范围：\n- 空腹血糖 4.4~7.0 mmol/L\n- 餐后2小时血糖 < 10.0 mmol/L\n- 糖化血红蛋白 < 7.0%\n老年人、有严重并发症或频繁低血糖者，目标可适当放宽，具体以医生意见为准。\n\nQ3：血糖多少要立即就医？\n\nA：\n- 血糖 ≥ 16.7 mmol/L，尤其伴随口渴、多尿、乏力、恶心呕吐、呼吸有烂苹果味，警惕糖尿病酮症酸中毒，需立即就医。\n- 血糖 ≤ 3.9 mmol/L 为低血糖，立即进食15克葡萄糖（约3~4片葡萄糖片或150ml果汁），15分钟后复测。\n- 若出现意识模糊、昏迷，不可强行喂食，应立即拨打120。\n\nQ4：测血糖前要空腹多久？\n\nA：空腹血糖要求至少8小时不摄入任何含热量食物，可少量饮水。一般建议前一天晚上10点后不再进食。\n\nQ5：手指采血要注意什么？\n\nA：\n1. 用温水洗手并擦干，避免用酒精后未干就采血（会稀释血样）。\n2. 选择手指侧面采血，疼痛较轻且血供丰富。\n3. 不要用力挤压手指，以免组织液混入影响结果。\n4. 采血针和试纸不要重复使用。\n5. 试纸注意避光防潮，开罐后3个月内用完。\n\nQ6：血糖波动大怎么办？\n\nA：记录完整的血糖日记（时间、数值、饮食、用药、运动情况），就诊时提供给医生。不要自行增减药量。常见波动原因包括饮食不规律、漏服药、感染、情绪波动、睡眠不足。\n\nQ7：吃什么能降血糖？\n\nA：没有食物能直接\"降血糖\"。饮食管理的核心是控制总热量、选择低升糖指数食物、定时定量进餐。\n推荐：全谷物、杂豆、绿叶蔬菜、菌菇类；\n限制：精制米面、含糖饮料、糕点、油炸食品、粥类（升糖快）。','慢病管理系统知识库','2024-06-01','2024-06-01','2型糖尿病患者及家属','1.0','血糖监测FAQ.pdf',NULL,'e3b5d7f9a1c2e4b6d8f0a2c4e6b8d0f2a4c6e8b0d2f4a6c8e0b2d4f6a8c0e2b4','常见问题 全部','血糖,FAQ,胰岛素,低血糖,饮食','','1',3,'admin','2026-10-08 11:37:33','admin','2026-10-12 16:18:09','0'),(101,'家庭血压测量的规范方法','1','0','指南','家庭自测血压的正确方法与注意事项','①测量前30分钟避免吸烟、饮酒、饮咖啡及剧烈运动，排空膀胱，静坐休息5分钟。②取坐位，上臂裸露并与心脏保持同一水平，袖带下缘距肘窝2~3cm。③每次测量2~3遍，间隔1分钟，取平均值。④建议早（起床后1小时内、服药前、早餐前）晚（睡前）各测1次，连续监测7天，去掉第1天数据取后6天平均值。⑤家庭血压≥135/85mmHg可视为血压升高。','中国高血压防治指南修订委员会','2024-08','2024-09','高血压及心血管疾病患者、家庭自测人群','2024版',NULL,NULL,NULL,'第一章 血压测量 1.4 家庭血压监测','家庭血压,测量方法,135/85,早晚各一次','血压,自测,家庭血压,测量方法','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(102,'居家血糖监测的规范方法','1','0','指南','指尖血糖监测的时机与判读','①空腹血糖指禁食8~10小时后测得的血糖；餐后2小时血糖从进食第一口饭开始计时。②监测频次：使用胰岛素者每日至少3次（空腹+餐后+睡前）；口服药治疗且血糖稳定者每周2~4次。③采血前用温水洗手并擦干，勿用酒精未干时采血，避免用力挤压手指。④血糖仪需定期与静脉血比对校准。','中华医学会糖尿病学分会','2024-06','2024-07','糖尿病患者及血糖监测人群','2024版',NULL,NULL,NULL,'第二章 血糖监测 2.3 自我血糖监测方案','血糖,空腹血糖,餐后2小时,监测频次,指尖血','血糖,监测,空腹,餐后,血糖仪','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(103,'高血压的诊断标准与分级','1','1','指南','诊室血压分级：1级140-159/90-99，2级160-179/100-109，3级≥180/110','在未使用降压药物的情况下，非同日3次测量诊室血压：收缩压≥140mmHg和/或舒张压≥90mmHg可诊断高血压。分级：1级（轻度）收缩压140~159或舒张压90~99；2级（中度）收缩压160~179或舒张压100~109；3级（重度）收缩压≥180或舒张压≥110。单纯收缩期高血压指收缩压≥140而舒张压<90。','中国高血压防治指南修订委员会','2024-08','2024-09','成人高血压患者','2024版',NULL,NULL,NULL,'第三章 诊断与分级 3.1 血压水平分类与定义','高血压,诊断标准,分级,140,90,180,110','高血压,分级,诊断,血压标准','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(104,'高血压患者的降压目标值','1','1','指南','一般患者＜140/90；可耐受者＜130/80；老年患者适当放宽','一般高血压患者降压目标为＜140/90mmHg；能耐受者和部分高危及以上患者可进一步降至＜130/80mmHg。65~79岁老年人首先降至＜150/90mmHg，如耐受可降至＜140/90mmHg；≥80岁老年人降至＜150/90mmHg即可。合并糖尿病或慢性肾病者，目标为＜130/80mmHg，但需监测肾功能与血钾。','中国高血压防治指南修订委员会','2024-08','2024-09','成人高血压患者','2024版',NULL,NULL,NULL,'第四章 治疗目标 4.1 降压目标','降压目标,140/90,130/80,老年人','高血压,降压目标,治疗目标','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(105,'生活方式干预：限盐与饮食（高血压）','1','1','指南','每日食盐＜5g，增加钾摄入，限制饮酒','①限制钠盐：每人每日食盐摄入量＜5g（约一啤酒瓶盖），减少酱油、腌制品、加工食品。②增加富钾食物：新鲜蔬菜、水果、豆类。③合理膳食：减少饱和脂肪与胆固醇，增加优质蛋白与膳食纤维。④戒烟限酒：不饮酒或严格限制。⑤控制体重：BMI＜24kg/m²，男性腰围＜90cm、女性＜85cm。','中国高血压防治指南修订委员会','2024-08','2024-09','高血压患者及高危人群','2024版',NULL,NULL,NULL,'第五章 治疗 5.2 生活方式干预','限盐,5g,低盐饮食,减重,戒烟限酒','高血压,饮食,限盐,生活方式','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(106,'高血压的用药原则与依从性','1','1','指南','小剂量起始、优先长效制剂、联合用药、长期坚持','①小剂量开始，逐步调整至目标血压。②优先选用每日1次的长效制剂，平稳控制24小时血压。③血压≥160/100mmHg或高于目标值20/10mmHg时可起始联合用药。④常用五大类：钙通道阻滞剂（CCB）、血管紧张素转换酶抑制剂（ACEI）、血管紧张素受体拮抗剂（ARB）、利尿剂、β受体阻滞剂。⑤不可自行停药或减量，血压正常是药物起效的表现，擅自停药可致血压反弹。','中国高血压防治指南修订委员会','2024-08','2024-09','成人高血压患者','2024版',NULL,NULL,NULL,'第六章 药物治疗 6.1 治疗原则','降压药,长效制剂,联合用药,依从性,不可停药','高血压,用药,降压药,依从性','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(107,'血压急症：什么情况必须立即就医','1','1','指南','血压≥180/110并伴胸痛、呼吸困难、剧烈头痛、视物模糊等','若血压≥180/110mmHg，同时出现以下任一症状，提示高血压急症，须立即拨打120就医：①剧烈头痛、头晕、恶心呕吐；②视力模糊或突然失明；③胸痛、胸闷、心悸、呼吸困难；④言语不清、肢体无力、口角歪斜（疑似卒中）；⑤意识模糊、抽搐。就医前应保持安静、半卧位，不要自行大量含服降压药。','中国高血压防治指南修订委员会','2024-08','2024-09','高血压患者','2024版',NULL,NULL,NULL,'第七章 特殊类型 7.3 高血压急症','高血压急症,180/110,胸痛,头痛,120,卒中','高血压,急症,急救,就医','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(108,'2型糖尿病的诊断标准','1','2','指南','空腹≥7.0、餐后2h或随机≥11.1、糖化≥6.5%','符合以下任一条件即可诊断糖尿病：①空腹血糖≥7.0mmol/L；②口服葡萄糖耐量试验（OGTT）2小时血糖≥11.1mmol/L；③随机血糖≥11.1mmol/L并伴典型症状（多饮、多尿、多食、体重下降）；④糖化血红蛋白（HbA1c）≥6.5%。无典型症状者需改日复测确认。空腹血糖6.1~6.9为空腹血糖受损，OGTT 2h 7.8~11.0为糖耐量减低。','中华医学会糖尿病学分会','2024-06','2024-07','成人','2024版',NULL,NULL,NULL,'第二章 诊断 2.1 诊断标准','糖尿病,诊断,空腹7.0,糖化,6.5%,11.1','糖尿病,诊断标准,血糖','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(109,'2型糖尿病的血糖控制目标','1','2','指南','一般HbA1c＜7.0%，空腹4.4~7.0，餐后＜10.0','多数非妊娠成年2型糖尿病患者的控制目标：糖化血红蛋白（HbA1c）＜7.0%；空腹血糖4.4~7.0mmol/L；餐后2小时血糖＜10.0mmol/L。年轻、病程短、无并发症者可更严格（HbA1c＜6.5%）；老年、病程长、有严重低血糖史或并发症者可适当放宽（HbA1c＜8.0%）。','中华医学会糖尿病学分会','2024-06','2024-07','成人2型糖尿病患者','2024版',NULL,NULL,NULL,'第三章 控制目标 3.1 血糖控制目标','糖化7.0,空腹4.4-7.0,餐后10.0,控制目标','糖尿病,血糖目标,糖化血红蛋白','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(110,'糖尿病饮食治疗原则','1','2','指南','控制总热量、均衡营养、低GI、定时定量','①控制每日总热量，维持理想体重。②碳水化合物占总热量50%~60%，优先选择低升糖指数（GI≤55）食物，如全谷物、杂豆、绿叶蔬菜。③限制添加糖与含糖饮料。④蛋白质占15%~20%，合并肾病者适当限制。⑤脂肪占20%~30%，以不饱和脂肪为主。⑥定时定量进餐，可少量多餐，避免餐后血糖剧烈波动。','中华医学会糖尿病学分会','2024-06','2024-07','糖尿病患者','2024版',NULL,NULL,NULL,'第五章 医学营养治疗 5.2 营养素分配','糖尿病饮食,低GI,总热量,定时定量,碳水','糖尿病,饮食,低GI,营养','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(111,'糖尿病运动治疗建议','1','2','指南','每周≥150分钟中等强度有氧运动，避免空腹运动','①每周至少150分钟中等强度有氧运动（如快走、慢跑、游泳、骑车），分配在3~5天，避免连续两天不运动。②每周2~3次抗阻训练。③运动宜在餐后1小时进行，避免空腹运动以防低血糖。④运动前监测血糖，＜5.6mmol/L应先加餐。⑤随身携带糖果或含糖饮料以防低血糖。⑥血糖＞16.7mmol/L或伴酮症时应暂停运动。','中华医学会糖尿病学分会','2024-06','2024-07','糖尿病患者','2024版',NULL,NULL,NULL,'第六章 运动治疗 6.1 运动原则','糖尿病运动,150分钟,餐后运动,低血糖','糖尿病,运动,低血糖','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(112,'低血糖的识别与处理','1','2','指南','血糖＜3.9mmol/L；立即进食15g葡萄糖，15分钟后复测','低血糖指血糖＜3.9mmol/L，表现为心慌、出汗、手抖、饥饿感、头晕、乏力，严重者意识模糊、昏迷。处理：立即口服15g葡萄糖（约3~4块方糖或150ml含糖饮料），15分钟后复测血糖；若仍＜3.9mmol/L，重复上述处理；血糖恢复后若距下一餐较久，可加食含蛋白质的小食。出现意识障碍者不可强行喂食，须立即送医。','中华医学会糖尿病学分会','2024-06','2024-07','使用胰岛素或促泌剂的患者','2024版',NULL,NULL,NULL,'第十章 低血糖 10.2 处理流程','低血糖,3.9,15g葡萄糖,出汗,手抖','低血糖,急救,葡萄糖','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(113,'糖尿病酮症与高血糖危象警示','1','2','指南','血糖＞16.7并伴口渴、多尿、恶心、呼吸深快、烂苹果味需急诊','当血糖＞16.7mmol/L，并出现以下表现时须立即就医：①极度口渴、多尿、乏力加重；②恶心、呕吐、腹痛；③呼吸深快、呼气有烂苹果味（酮味）；④意识模糊、嗜睡。上述提示糖尿病酮症酸中毒或高血糖高渗状态，属危及生命的急症，须立即拨打120。','中华医学会糖尿病学分会','2024-06','2024-07','糖尿病患者','2024版',NULL,NULL,NULL,'第九章 急性并发症 9.1 酮症酸中毒','酮症酸中毒,16.7,烂苹果味,呼吸深快,120','糖尿病,急症,酮症酸中毒,急救','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(114,'冠心病的危险因素与预防','1','3','指南','控制血压、血脂、血糖，戒烟，合理膳食与运动','冠心病主要危险因素：①高血压；②血脂异常（LDL-C升高）；③糖尿病；④吸烟；⑤肥胖与缺乏运动；⑥家族史。预防措施：控制血压＜140/90mmHg，LDL-C达标（一般＜1.8mmol/L），戒烟，限制饮酒，每周至少150分钟中等强度运动，控制体重，均衡饮食（多蔬果、全谷物、深海鱼，限饱和脂肪与反式脂肪）。','中华医学会心血管病学分会','2024-05','2024-06','冠心病患者及高危人群','2024版',NULL,NULL,NULL,'第三章 危险因素与一级预防 3.2 危险因素管理','冠心病,危险因素,LDL,吸烟,预防','冠心病,危险因素,预防','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(115,'心绞痛的识别与应对','1','3','指南','胸骨后压榨样疼痛，休息或含服硝酸甘油后3~5分钟缓解','典型心绞痛表现为胸骨后或心前区压榨样、闷胀样疼痛，常放射至左肩、左臂内侧、颈部或下颌，多在劳累、情绪激动、饱餐或受寒时诱发，持续数分钟，休息或舌下含服硝酸甘油后3~5分钟内缓解。若疼痛持续超过15~20分钟、程度剧烈、含服硝酸甘油不缓解，应高度怀疑急性心肌梗死，立即拨打120。','中华医学会心血管病学分会','2024-05','2024-06','冠心病患者','2024版',NULL,NULL,NULL,'第四章 临床表现 4.2 心绞痛','心绞痛,胸痛,硝酸甘油,压榨,放射','冠心病,心绞痛,胸痛','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(116,'急性心肌梗死的急救要点','1','3','指南','立即拨打120，静卧，嚼服阿司匹林，勿自行就医','疑似急性心肌梗死时：①立即拨打120，说明“疑似心梗”，等待专业转运，不自行驾车或步行去医院。②立即停止活动，就地静卧或半卧位，保持安静。③如无阿司匹林过敏及出血性疾病，可嚼服阿司匹林300mg。④保持呼吸道通畅，如有条件可吸氧。⑤如出现意识丧失、呼吸停止，立即行心肺复苏（CPR）。⑥黄金救治时间为发病后120分钟内开通血管。','中华医学会心血管病学分会','2024-05','2024-06','冠心病患者及公众','2024版',NULL,NULL,NULL,'第八章 急性冠脉综合征 8.4 急救','心梗,120,阿司匹林,CPR,黄金120分钟','冠心病,心梗,急救','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(117,'冠心病患者的运动与康复','1','3','指南','病情稳定后进行心脏康复，运动强度循序渐进','病情稳定的冠心病患者应进行心脏康复：①运动前需经医生评估（如运动负荷试验）。②以有氧运动为主（步行、骑车、太极拳），从低强度开始，每周3~5次，每次20~40分钟。③运动中出现胸痛、胸闷、气促、头晕应立即停止并就医。④避免在寒冷、饱餐后或情绪激动时运动。⑤可结合呼吸训练与放松训练。','中华医学会心血管病学分会','2024-05','2024-06','稳定期冠心病患者','2024版',NULL,NULL,NULL,'第九章 心脏康复 9.1 运动处方','冠心病运动,心脏康复,运动强度,循序渐进','冠心病,运动,康复','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(118,'慢阻肺的诊断与肺功能标准','1','4','指南','吸入支气管舒张剂后FEV1/FVC＜0.70可确诊','慢阻肺（COPD）的诊断需结合症状、危险因素接触史与肺功能检查。吸入支气管舒张剂后，第一秒用力呼气容积与用力肺活量比值（FEV1/FVC）＜0.70，可确定存在持续气流受限。按FEV1占预计值百分比分级：GOLD1（轻度）≥80%，GOLD2（中度）50%~79%，GOLD3（重度）30%~49%，GOLD4（极重度）＜30%。','中华医学会呼吸病学分会','2024-04','2024-05','慢阻肺患者及高危人群','2024版',NULL,NULL,NULL,'第二章 诊断与评估 2.2 肺功能','慢阻肺,FEV1,FVC,0.70,肺功能,GOLD','慢阻肺,诊断,肺功能','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(119,'慢阻肺的稳定期吸入治疗与用药依从性','1','4','指南','长期规律使用吸入制剂，正确掌握吸入装置用法','①稳定期以吸入药物治疗为主，常用支气管舒张剂（LAMA、LABA）及联合制剂（LABA+LAMA），频繁急性加重者可加用吸入糖皮质激素。②吸入治疗需长期规律使用，即使症状缓解也不可自行停药。③必须掌握正确的吸入装置使用方法（如噘嘴吸气、屏气10秒），用后漱口以防口腔真菌感染。④建议定期复诊评估肺功能与症状。','中华医学会呼吸病学分会','2024-04','2024-05','慢阻肺稳定期患者','2024版',NULL,NULL,NULL,'第四章 稳定期治疗 4.3 吸入药物治疗','慢阻肺,吸入剂,LAMA,LABA,吸入装置,漱口','慢阻肺,用药,吸入治疗','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(120,'慢阻肺急性加重的识别','1','4','指南','呼吸困难加重、痰量增多、痰变脓性需及时就医','慢阻肺急性加重指短期内呼吸困难、咳嗽、咳痰等症状明显加重，典型表现为：①呼吸困难较平时明显加重；②痰量增多；③痰液变黄变脓。出现以下情况须立即就医或拨打120：①严重呼吸困难、不能平卧、说话断续；②口唇或指甲发紫（发绀）；③意识模糊、嗜睡；④心率明显增快、下肢水肿加重；⑤家庭氧疗后症状无改善。','中华医学会呼吸病学分会','2024-04','2024-05','慢阻肺患者','2024版',NULL,NULL,NULL,'第五章 急性加重 5.2 识别与分级','慢阻肺急性加重,痰量,脓痰,发绀,120','慢阻肺,急性加重,急救','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(121,'慢阻肺呼吸康复与营养支持','1','4','指南','缩唇呼吸、腹式呼吸训练，保证蛋白质摄入','①呼吸训练：缩唇呼吸（鼻吸口呼，呼气时口唇缩成吹口哨状，呼气时间是吸气的2~3倍）、腹式呼吸，每日2~3次，每次10~15分钟。②运动训练：在耐受范围内进行步行、上肢训练，逐步增加时长。③营养支持：慢阻肺患者常伴营养不良与呼吸肌无力，应保证蛋白质摄入（1.2~1.5g/kg体重/天），少量多餐，因进餐耗氧，餐间适当休息。④家庭氧疗者遵医嘱持续低流量吸氧（一般1~2L/min，每日≥15小时）。','中华医学会呼吸病学分会','2024-04','2024-05','慢阻肺患者','2024版',NULL,NULL,NULL,'第六章 康复与支持 6.1 呼吸康复','慢阻肺,缩唇呼吸,腹式呼吸,蛋白质,氧疗','慢阻肺,康复,呼吸训练,营养','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(122,'慢阻肺患者戒烟与疫苗预防','1','4','指南','戒烟是延缓肺功能下降最有效措施，建议接种流感与肺炎疫苗','①戒烟是延缓慢阻肺进展、保护肺功能最重要的措施，任何阶段戒烟均有益。可借助戒烟门诊、行为干预与药物辅助。②避免生物燃料烟雾、粉尘及空气污染暴露。③建议每年接种流感疫苗、按医嘱接种肺炎球菌疫苗，以减少急性加重与住院风险。④冬季注意保暖，减少呼吸道感染。','中华医学会呼吸病学分会','2024-04','2024-05','慢阻肺患者及吸烟人群','2024版',NULL,NULL,NULL,'第七章 预防 7.1 戒烟与免疫接种','慢阻肺,戒烟,流感疫苗,肺炎疫苗,预防','慢阻肺,戒烟,疫苗,预防','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(123,'为什么血压正常了也不能停降压药','2','1','科普','血压达标是药物作用的结果，停药易致反弹','很多患者发现血压降到正常就自行停药，这是常见误区。血压达标恰恰说明药物正在起效，血管和心脏得到了保护。擅自停药后，血压往往在短时间内反弹，甚至高于治疗前，增加脑卒中、心肌梗死风险。降压治疗通常是长期的，是否减量、换药必须由医生根据动态血压评估后决定。','系统整理（非权威）','2024-09','2024-09','高血压患者','—',NULL,NULL,NULL,'科普解释','降压药,停药,反弹,依从性','高血压,停药,科普','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(124,'糖尿病为什么强调“餐后血糖”','2','2','科普','餐后血糖更能反映饮食与血糖波动','空腹血糖反映基础血糖水平，而餐后2小时血糖反映进食后胰岛素的调节能力。很多患者空腹血糖正常，餐后血糖却明显升高——这是心血管并发症的重要危险因素。因此糖尿病患者不仅要关注空腹血糖，也要重视餐后血糖，通过控制主食种类与总量、餐后适度活动来平稳餐后血糖。','系统整理（非权威）','2024-09','2024-09','糖尿病患者','—',NULL,NULL,NULL,'科普解释','餐后血糖,血糖波动,并发症','糖尿病,餐后血糖,科普','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(125,'胸痛一定要立刻打120吗','2','3','科普','持续超过15分钟不缓解的胸痛须立即呼叫急救','并非所有胸痛都是心脏问题，但心源性胸痛凶险且进展快。如果胸痛呈压榨样，位于胸骨后，持续超过15分钟且含服硝酸甘油不缓解，或伴大汗、恶心、濒死感，务必立即拨打120，不要自行前往医院。宁可“虚惊一场”，也不要错过救治黄金时间。','系统整理（非权威）','2024-09','2024-09','冠心病患者及公众','—',NULL,NULL,NULL,'科普解释','胸痛,120,黄金时间,心梗','冠心病,胸痛,科普','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0'),(126,'慢阻肺患者为什么要注意加强营养','2','4','科普','呼吸本身消耗能量，营养不良会削弱呼吸肌','慢阻肺患者呼吸费力，呼吸肌耗能明显高于常人，容易出现体重下降和肌肉减少（尤其呼吸肌）。营养不良会进一步削弱呼吸肌力量，形成恶性循环。因此患者应保证足够的蛋白质和热量摄入，少量多餐，避免因进餐后气短而减少进食。','系统整理（非权威）','2024-09','2024-09','慢阻肺患者','—',NULL,NULL,NULL,'科普解释','慢阻肺,营养,呼吸肌,蛋白质','慢阻肺,营养,科普','1',0,'system','2026-10-08 22:04:18',NULL,NULL,'0');
