--
-- Table structure for table `mp_bind_apply`
--

DROP TABLE IF EXISTS `mp_bind_apply`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mp_bind_apply` (
  `apply_id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `family_user_id` bigint NOT NULL COMMENT '家属用户ID',
  `family_name` varchar(50) DEFAULT '' COMMENT '家属姓名',
  `patient_id` bigint NOT NULL COMMENT '申请绑定的患者ID',
  `patient_name` varchar(50) DEFAULT '' COMMENT '患者姓名',
  `relation` varchar(20) DEFAULT '' COMMENT '与患者关系',
  `apply_remark` varchar(500) DEFAULT NULL COMMENT '申请说明',
  `patient_status` char(1) DEFAULT '0' COMMENT '患者确认状态(0待确认 1已同意 2已拒绝)',
  `doctor_status` char(1) DEFAULT '0' COMMENT '医生审核状态(0待审核 1已通过 2已驳回)',
  `doctor_id` bigint DEFAULT NULL COMMENT '审核医生ID',
  `doctor_name` varchar(50) DEFAULT '' COMMENT '审核医生',
  `audit_opinion` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `bind_status` char(1) DEFAULT '0' COMMENT '最终绑定状态(0申请中 1绑定成功 2已拒绝)',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `patient_time` datetime DEFAULT NULL COMMENT '患者确认时间',
  `audit_time` datetime DEFAULT NULL COMMENT '医生审核时间',
  PRIMARY KEY (`apply_id`),
  KEY `idx_family` (`family_user_id`),
  KEY `idx_patient` (`patient_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='家属-患者绑定申请表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `mp_bind_apply`
--

